// Some portions generated by Claude

// New Repository's type chooser: the server's templates grouped by the store they use, in the server's order, and a
// line under the chooser saying what the chosen type is.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function loadWorkbench() {
    const workbench = {};
    const window = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    window.workbench = context.workbench;
    return context.workbench;
}

function runtime() {
    return {
        nothing: '',
        html(strings, ...values) { return { strings: Array.from(strings), values }; },
        render(template, mount) { mount.template = template; }
    };
}

/** The template as markup; event bindings (functions) are kept so a test can call them. */
function flatten(template, handlers) {
    if (Array.isArray(template)) {
        return template.map(entry => flatten(entry, handlers)).join('');
    }
    if (template && Array.isArray(template.strings)) {
        return template.strings.reduce((result, fragment, index) => {
            if (index >= template.values.length) {
                return result + fragment;
            }
            const value = template.values[index];
            if (typeof value === 'function') {
                handlers.push(value);
                return result + fragment + 'handler-' + (handlers.length - 1);
            }
            return result + fragment + flatten(value, handlers);
        }, '');
    }
    return template === null || typeof template === 'undefined' ? '' : String(template);
}

const templates = [
    ['memory', 'Memory Store'], ['memory-rdfs', 'Memory Store + RDFS'], ['native-shacl', 'Native Store + SHACL'],
    ['remote', 'Remote RDF Store'], ['sparql', 'SPARQL endpoint proxy'], ['federate', 'Federation'],
    ['lmdb', 'LMDB Store'], ['acme-graph', 'Acme Graph Store']
];

function chooser() {
    const workbench = loadWorkbench();
    const model = { viewId: 'create', vars: ['type', 'label'], rows: templates, rowCount: templates.length, metadata: {} };
    const handlers = [];
    const markup = flatten(workbench.views.pageTemplate(model,
        { basePath: '/workbench', repositoryId: 'NONE', workbench: {} }, runtime()), handlers);
    const start = markup.indexOf('id="create-type-form"');
    return { form: markup.substring(start, markup.indexOf('</form>', start)), handlers };
}

test('the repository types are grouped by store in the server\'s order', () => {
    const { form } = chooser();
    const groups = Array.from(form.matchAll(/<optgroup label="?([^">]+?)"?>([\s\S]*?)<\/optgroup>/g))
        .map(group => [group[1], Array.from(group[2].matchAll(/<option value="?([\w-]+)"?/g)).map(option => option[1])]);
    assert.deepEqual(groups, [
        ['Memory', ['memory', 'memory-rdfs']],
        ['Native', ['native-shacl']],
        ['Remote and federation', ['remote', 'sparql', 'federate']],
        ['LMDB', ['lmdb']],
        ['Other', ['acme-graph']]
    ]);
});

test('a line under the type chooser says what the chosen type is', () => {
    const { form, handlers } = chooser();
    assert.match(form, /<select id="type" name="type" aria-describedby="type-description"/);
    const description = /<p id="type-description" class="workbench-field__help"[^>]*>([^<]*)<\/p>/.exec(form);
    assert.ok(description, 'the description is a help line under the chooser');
    assert.equal(description[1], 'Keeps all data in memory and can save it to disk.');
    const change = /<select id="type"[^>]*@change=handler-(\d+)/.exec(form);
    assert.ok(change, 'choosing a type updates the line');
    const line = { textContent: '', hidden: false };
    const select = { value: 'native-shacl', ownerDocument: { getElementById: id => id === 'type-description' ? line : null } };
    handlers[Number(change[1])]({ currentTarget: select });
    assert.equal(line.textContent, 'Stores the data on disk in B-tree indexes, for data larger than memory. '
        + 'Validates every change against SHACL shapes.');
    assert.equal(line.hidden, false);
    select.value = 'acme-graph';
    handlers[Number(change[1])]({ currentTarget: select });
    assert.equal(line.textContent, '');
    assert.equal(line.hidden, true, 'a type the Workbench does not know has no line');
});
